  void mapRoles(){if(!havePack){status->setText("请先导入条件规则包");return;}
    QDialog dialog(this);dialog.setWindowTitle("批量测点角色映射（不修改规则阈值）");dialog.resize(850,450);auto* layout=new QVBoxLayout(&dialog);QTableWidget table;const auto roles=conditionRoles(pack);table.setColumnCount(5);table.setHorizontalHeaderLabels({"标准角色","原始字段名（精确匹配）","输入单位","倍率","轴号 0–3"});table.setRowCount(roles.size());table.horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);int row=0;
    for(auto i=roles.begin();i!=roles.end();++i,++row){const auto binding=bindings.value(i.key());auto* name=new QTableWidgetItem(i.key());name->setFlags(name->flags()&~Qt::ItemIsEditable);table.setItem(row,0,name);table.setItem(row,1,new QTableWidgetItem(binding.field));auto* unit=new QComboBox;unit->addItems({"","rpm","rad/s","deg","rad","m/s2","g","mm/s","m/s"});unit->setCurrentText(binding.unit);table.setCellWidget(row,2,unit);auto* scale=new QDoubleSpinBox;scale->setDecimals(9);scale->setRange(.000000001,1e9);scale->setValue(binding.scale);table.setCellWidget(row,3,scale);auto* axis=new QSpinBox;axis->setRange(0,3);axis->setValue(binding.axis);table.setCellWidget(row,4,axis);}
    layout->addWidget(&table);QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);layout->addWidget(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
    if(dialog.exec()!=QDialog::Accepted)return;QJsonObject saved;bindings.clear();for(int i=0;i<table.rowCount();++i){RoleBinding b;b.field=table.item(i,1)->text().trimmed();b.unit=qobject_cast<QComboBox*>(table.cellWidget(i,2))->currentText();b.scale=qobject_cast<QDoubleSpinBox*>(table.cellWidget(i,3))->value();b.axis=qobject_cast<QSpinBox*>(table.cellWidget(i,4))->value();const auto role=table.item(i,0)->text();bindings[role]=b;saved[role]=QJsonObject{{"field",b.field},{"unit",b.unit},{"scale",b.scale},{"axis",b.axis}};}QSettings().setValue(profileKey(),QJsonDocument(saved).toJson(QJsonDocument::Compact));invalidate();
  }
  void exportSummary(){const auto path=QFileDialog::getSaveFileName(this,"导出批量摘要",{},"CSV (*.csv)");if(path.isEmpty())return;QSaveFile file(path);const auto bytes=summaryCsv();if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())status->setText("批量摘要保存失败："+file.errorString());else status->setText("已导出全部任务（包括当前被筛选隐藏的任务）");}
protected:
  bool eventFilter(QObject* watched,QEvent* event)override{if(running&&event->type()==QEvent::Close&&watched==window()){status->setText("请先取消批量任务，等待当前读取结束后再关闭窗口");return true;}return QWidget::eventFilter(watched,event);}
