    setObjectName("diagnosisBatchPage");auto* root=new QVBoxLayout(this);controls=new QWidget;auto* controlsLayout=new QVBoxLayout(controls);controlsLayout->setContentsMargins(0,0,0,0);root->addWidget(controls);auto* top=new QHBoxLayout;controlsLayout->addLayout(top);auto button=[&](QString name,auto action){auto* b=new QPushButton(name);top->addWidget(b);connect(b,&QPushButton::clicked,this,action);return b;};
    button("返回单条",back);button("添加录波",[this]{addFiles(QFileDialog::getOpenFileNames(this,"添加本地录波",{},"TXT / CSV (*.txt *.csv)"));});button("关联 SC",[this]{link(false);});button("关联 ActionList",[this]{link(true);});
    button("规则包",[this]{const auto path=QFileDialog::getOpenFileName(this,"导入条件规则包",{},"JSON (*.json)");if(path.isEmpty())return;try{QFile f(path);packCheck(f.open(QIODevice::ReadOnly)&&f.size()<=2*1024*1024,"无法读取规则包或超过 2 MiB");setPack(parseConditionPack(f.readAll()));}catch(const std::exception& e){status->setText(QString::fromUtf8(e.what()));}});button("角色映射",[this]{mapRoles();});
    auto* more=new QToolButton;more->setText("任务操作");more->setPopupMode(QToolButton::InstantPopup);auto* menu=new QMenu(more);more->setMenu(menu);top->addWidget(more);
    auto action=[&](QString text,auto slot){connect(menu->addAction(text),&QAction::triggered,this,slot);};
    action("所选重新排队（保留历史报告文件）",[this]{for(auto row:selected())requeue(row);});action("清除所选事件关联",[this]{for(auto row:selected()){entries[row].job.sc.clear();entries[row].job.actions.clear();requeue(row);}invalidate();});
    action("指定所选事件中心（UTC）",[this]{const auto rows=selected();if(rows.empty())return;QDialog d(this);d.setWindowTitle("事件中心 UTC");auto* l=new QVBoxLayout(&d);QDateTimeEdit edit(QDateTime::currentDateTimeUtc());edit.setTimeSpec(Qt::UTC);edit.setDisplayFormat("yyyy-MM-dd HH:mm:ss.zzz");l->addWidget(&edit);QDialogButtonBox b(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);l->addWidget(&b);connect(&b,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(&b,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()==QDialog::Accepted)for(auto row:rows){entries[row].job.manualCenter=true;entries[row].job.center=edit.dateTime().toMSecsSinceEpoch();requeue(row);}invalidate();});
    action("恢复所选文件名时间 / 数据中点",[this]{for(auto row:selected()){entries[row].job.manualCenter=false;requeue(row);}invalidate();});action("移除所选任务",[this]{auto rows=selected();std::sort(rows.begin(),rows.end(),std::greater<int>());for(auto row:rows){entries.removeAt(row);tasks->removeRow(row);}applyFilter();});
    packLabel=new QLabel("未导入规则包；此阶段支持本地 TXT / CSV，不改变单条录波数据");packLabel->setWordWrap(true);packLabel->setTextFormat(Qt::PlainText);controlsLayout->addWidget(packLabel);
