    auto* windowRow=new QHBoxLayout;before=new QSpinBox;after=new QSpinBox;for(auto* spin:{before,after}){spin->setRange(0,3600);spin->setValue(30);spin->setSuffix(" s");}scOffset=new QSpinBox;scOffset->setRange(-86400000,86400000);scOffset->setSuffix(" ms");windowRow->addWidget(new QLabel("中心前"));windowRow->addWidget(before);windowRow->addWidget(new QLabel("中心后"));windowRow->addWidget(after);windowRow->addWidget(new QLabel("SC 原始时间 +"));windowRow->addWidget(scOffset);form->addRow("分析窗口",windowRow);
    pending=new QCheckBox("包含待验证规则（仅试跑）");pending->setObjectName("batchIncludePending");identity=new QCheckBox("已核对关联事件与录波为同一机组、同一时间体系");scComplete=new QCheckBox("已确认 SC 覆盖本次窗口");actionsComplete=new QCheckBox("已确认 ActionList 覆盖本次窗口");for(auto* c:{pending,identity,scComplete,actionsComplete})form->addRow(c);
    auto* outRow=new QHBoxLayout;output=new QLineEdit;output->setObjectName("batchOutputDirectory");output->setPlaceholderText("必选：本地报告保存目录");auto* choose=new QPushButton("选择目录");outRow->addWidget(output);outRow->addWidget(choose);form->addRow("报告目录",outRow);connect(choose,&QPushButton::clicked,this,[this]{const auto dir=QFileDialog::getExistingDirectory(this,"批量报告目录");if(!dir.isEmpty())output->setText(dir);});
    confirmed=new QCheckBox("已核对本批厂商/机型/固件、时间、字段单位和轴号；缺测不作为正常");confirmed->setObjectName("batchMappingsConfirmed");controlsLayout->addWidget(confirmed);
    auto* bar=new QHBoxLayout;controlsLayout->addLayout(bar);filter=new QComboBox;filter->addItems({"全部","待运行","运行中","完成证据计算","数据不足/质量异常","失败","已取消","机型不适用","没有可执行条件"});bar->addWidget(filter);auto* run=new QPushButton("运行待办 / 重试失败");run->setObjectName("batchRun");bar->addWidget(run);auto* exportButton=new QPushButton("导出批量摘要");bar->addWidget(exportButton);bar->addStretch();connect(run,&QPushButton::clicked,this,[this]{runPending();});connect(exportButton,&QPushButton::clicked,this,[this]{exportSummary();});connect(filter,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{tasks->clearSelection();applyFilter();});
    views=new QStackedWidget;root->addWidget(views,1);tasks=new QTableWidget(0,8);tasks->setObjectName("diagnosisBatchTasks");tasks->setHorizontalHeaderLabels({"状态","录波","SC","ActionList","中心时间 UTC","尝试","错误原因","报告文件"});tasks->setSelectionBehavior(QAbstractItemView::SelectRows);tasks->setEditTriggers(QAbstractItemView::NoEditTriggers);tasks->horizontalHeader()->setSectionResizeMode(QHeaderView::Interactive);tasks->horizontalHeader()->setDefaultSectionSize(150);tasks->setSortingEnabled(false);views->addWidget(tasks);connect(tasks,&QTableWidget::cellDoubleClicked,this,[this](int row,int){showDetails(row);});auto* detailsPage=new QWidget;auto* dlayout=new QVBoxLayout(detailsPage);auto* returnButton=new QPushButton("返回批量列表");dlayout->addWidget(returnButton);connect(returnButton,&QPushButton::clicked,this,[this]{views->setCurrentIndex(0);});detail=new QPlainTextEdit;detail->setReadOnly(true);detail->setObjectName("batchResultDetails");dlayout->addWidget(detail);views->addWidget(detailsPage);
